function sanitizeName(name, maxLength) {
    if (name == null) return "";
    return name.replace(/[^a-zA-Z]/g, " ").substring(0, maxLength);
  }

  function extractMiddleName(fullName) {
    if (!fullName) return '';
    const nameParts = fullName.trim().split(' ');
    if (nameParts.length > 2) {
      return nameParts[1].charAt(0).toUpperCase();
    }
    return '';
  }

  const personal = payload.personalInformation;

  // Guard: drop non-lead requests that arrive with no applicant data instead of
  // crashing below. (In Pipedream this lived in the constants step; our Constants
  // node can't run logic, so it moves here.)
  if (!personal) {
    return { exit: true };
  }

  const firstName = personal.firstName;
  const lastName = personal.lastName;
  const middleName = extractMiddleName(firstName);

  return {
    firstName: sanitizeName(firstName, 15),
    lastName: sanitizeName(lastName, 25),
    middleName: sanitizeName(middleName, 15)
  };

function transformToSalesforceFormat(inputData, bidspokeLink, parsedName) {
   const personal = inputData.personalInformation || {};
   const loan = inputData.loanInformation || {};
   const mortgage = inputData.mortgageInformation || {};
   const credit = inputData.creditInformation || {};
   const financial = inputData.financialInformation || {};
   const education = inputData.educationInformation || {};
   const legal = inputData.legalInformation || {};
   const session = inputData.sessionInformation || {};

   const mapEmploymentStatus = (status) => {
     if (!status) return 'Other';
     const statusMap = {
       'employed': 'Employed',
       'employed_full_time': 'employed_full_time',
       'employed_part_time': 'employed_part_time',
       'military': 'Military',
       'not_employed': 'not_employed',
       'self_employed': 'self_employed',
       'retired': 'Retired',
       'other': 'Other'
     };
     return statusMap[status.toLowerCase()] || 'Other';
   };

   const mapEducationLevel = (level) => {
     if (!level) return 'Other';
     const levelMap = {
       'high_school': 'high_school',
       'associate': 'Associate',
       'bachelors': 'Bachelors',
       'masters': 'Masters',
       'doctorate': 'Doctorate',
       'other_grad_degree': 'other_grad_degree',
       'certificate': 'Certificate',
       'did_not_graduate': 'did_not_graduate',
       'still_enrolled': 'still_enrolled',
       'other': 'Other'
     };
     return levelMap[level.toLowerCase()] || 'Other';
   };

   const mapLoanPurpose = (purpose) => {
     if (!purpose) return 'Other';
     const purposeMap = {
       'auto': 'Auto', 'auto_purchase': 'auto_purchase', 'auto_refinance': 'auto_refinance',
       'baby': 'Baby', 'boat': 'Boat', 'business': 'Business', 'car_repair': 'car_repair',
       'cosmetic': 'Cosmetic', 'credit_card_refi': 'credit_card_refi',
       'debt_consolidation': 'debt_consolidation', 'emergency': 'Emergency',
       'engagement': 'Engagement', 'green': 'Green', 'home_improvement': 'home_improvement',
       'home_purchase': 'home_purchase', 'home_refi': 'home_refi',
       'household_expenses': 'household_expenses', 'large_purchases': 'large_purchases',
       'life_event': 'life_event', 'medical_dental': 'medical_dental', 'motorcycle': 'Motorcycle',
       'moving_relocation': 'moving_relocation', 'other': 'Other', 'rv': 'Rv',
       'special_occasion': 'special_occasion', 'student_loan': 'student_loan',
       'student_loan_refi': 'student_loan_refi', 'taxes': 'Taxes', 'unknown': 'Unknown',
       'vacation': 'Vacation', 'wedding': 'Wedding'
     };
     return purposeMap[purpose.toLowerCase()] || 'Other';
   };

   const mapPaymentFrequency = (frequency) => {
     if (!frequency) return 'Monthly';
     const frequencyMap = {
       'weekly': 'Weekly', 'biweekly': 'biweekly', 'twice_monthly': 'twice_monthly', 'monthly': 'Monthly'
     };
     return frequencyMap[frequency.toLowerCase()] || 'Monthly';
   };

   const mapCreditRating = (rating) => {
     if (!rating) return 'Poor (<600)';
     const ratingMap = {
       'excellent': 'Excellent (720+)',
       'good': 'Good (660-719)',
       'fair': 'Fair (620-659)',
       'poor': 'Poor (<600)',
       'limited': 'Poor (<600)',
       'unknown': 'Poor (<600)'
     };
     return ratingMap[rating.toLowerCase()] || 'Poor (<600)';
   };

   const mapPropertyStatus = (status) => {
     if (!status) return 'Rent';
     const statusMap = {
       'own_outright': 'Own Outright',
       'own_with_mortgage': 'Own with Mortgage',
       'rent': 'Rent'
     };
     return statusMap[status.toLowerCase()] || 'Rent';
   };

   const formatPhoneNumber = (phone) => {
     if (!phone) return '';
     const digits = phone.replace(/\D/g, '');
     if (digits.length === 10) {
       return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
     }
     return phone;
   };

   const formatSSN = (ssn) => {
     if (!ssn) return '';
     return ssn.replace(/\D/g, '');
   };

   const safeBirthDate = (dob) => {
     if (!dob) return '1901-01-01';
     const d = new Date(dob + 'T00:00:00Z');
     if (isNaN(d.getTime())) return '1900-01-01';
     if (d.getUTCFullYear() < 1900) return '1900-01-01';
     return dob;
   };

   return {
     "Last_Name__c": parsedName.lastName || '',
     "Middle_Name__c": parsedName.middleName || '',
     "First_Name__c": parsedName.firstName || '',
     "State__c": personal.state || '',
     "City__c": personal.city || '',
     "Zip__c": personal.zipcode || '',
     "Email__c": personal.email || '',
     "Phone__c": formatPhoneNumber(personal.primaryPhone),
     "BirthDate__c": safeBirthDate(personal.dateOfBirth),
     "Street__c": personal.address1 || '',
     "AptSuite__c": personal.address2 || '',
     "LoanAmount__c": loan.loanAmount || 0,
     "LoanPurpose__c": mapLoanPurpose(loan.purpose),
     "IncomePmtFrequency__c": mapPaymentFrequency(financial.employmentPayFrequency),
     "AnnualIncomeBeforeTaxes__c": financial.annualIncome || 0,
     "EmploymentStatus__c": mapEmploymentStatus(financial.employmentStatus),
     "EducationLevel__c": mapEducationLevel(education.educationLevel),
     "SocialSecurityNumber__c": formatSSN(personal.ssn),
     "RentOrOwn__c": mapPropertyStatus(mortgage.propertyStatus),
     "ApproximateCreditRating__c": mapCreditRating(credit.providedCreditRating),
     "LeadUUID__c": inputData.leadUuid,
     "SubaccountUUID__c": inputData.subAccountUuid,
     "Source__c": "Engine",
     "ProspectTraceId__c": bidspokeLink,
     "TCPAConsentFlag__c": legal.consentsToTcpa,
     "FCRAConsentFlag__c": legal.consentsToFcra,
     "User_Agent__c": (session.userAgent || '').slice(0, 255),
     "User_IP__c": session.ipAddress,
   };
 }

 try {
   return transformToSalesforceFormat(payload, execution.bidspoke_link, steps.parsed_name.output);
 } catch (error) {
   console.error('Error transforming data:', error);
   return { response: { status: 500, body: { lead_id: payload.leadUuid, status: "error", reason: "internal server error" } } };
 }

async function transformToGigFi(body, refId, leadAffiliate, leadProvider, leadCampaign, subAccountBids) {
  const personal = body.personalInformation || {};
  const loan = body.loanInformation || {};
  const financial = body.financialInformation || {};
  const mortgage = body.mortgageInformation || {};
  const session = body.sessionInformation || {};

  const mapIncomeType = (status) => {
    const map = {
      'employed': '1', 'employed_full_time': '1', 'employed_part_time': '1',
      'military': '6', 'not_employed': '6', 'self_employed': '5',
      'retired': '4', 'other': '6'
    };
    return map[(status || '').toLowerCase()] || '6';
  };

  const mapPayFrequency = (freq) => {
    const map = { 'weekly': '1' };
    return map[(freq || '').toLowerCase()] || '2';
  };

  const formatSSN = (ssn) => (ssn || '').replace(/\D/g, '');

  const formatPhone = (phone) => {
    const digits = (phone || '').replace(/\D/g, '');
    if (digits.length === 10) return `${digits.slice(0, 3)}-${digits.slice(3, 6)}-${digits.slice(6)}`;
    return phone || '';
  };

  const monthlyIncome = financial.annualIncome ? +(financial.annualIncome / 12).toFixed(2) : 0;

  const nextPayDay = (() => {
    const d = new Date();
    d.setDate(d.getDate() + 7);
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${mm}/${dd}/${d.getFullYear()}`;
  })();

  const minBidValue = subAccountBids?.[body.subAccountUuid] ?? null;

  return {
    data: {
      RefID: refId || body.leadUuid || '',
      LeadAffiliate: leadAffiliate || body.subAccountUuid || '',
      LeadCost: 0,
      min_bid_value: minBidValue ?? 0.00,
      Firstname: personal.firstName || '',
      Lastname: personal.lastName || '',
      SSN: formatSSN(personal.ssn),
      Email: personal.email || '',
      DOB: personal.dateOfBirth || '',
      Language: 'e',
      Military: 'n',
      HomeAddress: personal.address1 || '',
      HomeCity: personal.city || '',
      HomeState: personal.state || '',
      HomeZip: personal.zipcode || '',
      HomePhone: formatPhone(personal.primaryPhone),
      CellPhone: formatPhone(personal.primaryPhone),
      HomeOwner: ['own_outright', 'own_with_mortgage'].includes(mortgage.propertyStatus) ? 'y' : 'n',
      BankInfo: { AccountToUse: 'C' },
      EmploymentInfo: {
        MonthlyIncome: monthlyIncome,
        PayFrequency: mapPayFrequency(financial.employmentPayFrequency),
        IncomeType: mapIncomeType(financial.employmentStatus),
        PayrollType: '2',
        NextPayDay: nextPayDay,
      },
      LoanInfo: { Amount: loan.loanAmount || 0 },
      LeadProvider: leadProvider || '',
      LeadCampaign: leadCampaign || loan.purpose || '',
      ClientIPAddress: session.ipAddress || ''
    },
    control: { execution_mode: 'sync' },
    mock_data: {},
    metadata: {},
  };
}

async function makeGigFiRequest(reqPayload, url, apiKey) {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Api-Key': apiKey },
      body: JSON.stringify(reqPayload),
    });
    const respData = await response.json().catch(() => null);
    if (!response.ok) {
      return { error: true, statusCode: response.status, message: JSON.stringify(respData) };
    }
    return { error: false, statusCode: 200, data: respData };
  } catch (error) {
    return { error: true, statusCode: 500, message: error.message };
  }
}

async function makeGigFiRequestWithRetry(reqPayload, url, apiKey) {
  let result = await makeGigFiRequest(reqPayload, url, apiKey);
  if (result.error && result.statusCode >= 500 && result.statusCode < 600) {
    await new Promise((r) => setTimeout(r, 250));
    result = await makeGigFiRequest(reqPayload, url, apiKey);
  }
  return result;
}

const apiKey = env.GIGFI_API_KEY;
if (!apiKey) {
  throw new Error("GIGFI_API_KEY env var is not set");
}

const ENDPOINT_URL = "https://risk.bf9baa41.decide.taktile.com/run/api/v1/flows/gigfileads/decide";
const LEAD_PROVIDER = "Pennie";

const applicantId = steps.create_applicant.output.body.id;
const subAccountBids = steps.constants.output.GigfiSubAccountMinBids || {};

const formattedBody = await transformToGigFi(
  payload,
  applicantId,
  payload.subAccountUuid,
  LEAD_PROVIDER,
  payload.loanInformation && payload.loanInformation.purpose,
  subAccountBids
);

const result = await makeGigFiRequestWithRetry(formattedBody, ENDPOINT_URL, apiKey);

if (result.error) {
  console.error('Error submitting lead to GigFi:', result.message);
  return { response: { status: 500, body: { lead_id: payload.leadUuid, status: "error", reason: "internal server error" } } };
}

return result;

const gigfiData = steps.ping_gigfi.output.data.data;
const gigfiResult = gigfiData.status;
const gigfiBid = gigfiData.bid_amount;
const constants = steps.constants.output;
const subAccountUuid = payload.subAccountUuid;

const floor = constants.GigfiSubAccountMinBids?.[subAccountUuid];

// Shared values used by the patch_applicant_* Salesforce Update nodes.
// (Templates can't do math / ?? / || / dynamic keys, so we compute here.)
const patch = {
  externalPartnerBid: gigfiBid ?? null,
  minBidAmt: (gigfiData && gigfiData.min_bid_value != null) ? gigfiData.min_bid_value : floor,
  redirectUrl: gigfiData && gigfiData.redirect_url,
  rejectionReason: gigfiData && gigfiData.rejection_reason,
  ts: new Date().toISOString(),
};

// --- unqualified ---
if (!Number(gigfiBid) || Number(gigfiBid) <= 0 || gigfiResult !== "ACCEPTED") {
  const reason = "unqualified_lead";
  return {
    body: { lead_id: payload.leadUuid, status: "rejected", reason },
    ...patch,
    lsRejectionReason: patch.rejectionReason || reason,
  };
}

// --- below threshold ---
if (floor !== undefined && Number(gigfiBid) < floor) {
  const reason = "bid_below_threshold";
  return {
    body: { lead_id: payload.leadUuid, status: "rejected", reason },
    ...patch,
    lsRejectionReason: patch.rejectionReason || reason,
  };
}

// --- offer (BID) ---
const bidAmount = gigfiBid * constants.multiplier;

// The hosts that get the link token (#2092): the block below signs a link to these only.
const LINK_TOKEN_HOSTS = ['trypennie.com', 'www.trypennie.com', 'reservemyloan.com'];
// BEGIN link token (#2089)
// trypennie.com refuses a link to a Salesforce record created after its cutoff unless the
// link carries ?t=<token>: HMAC-SHA256 of the first 15 characters of the record id, keyed
// with LINK_TOKEN_SECRET, base64url with no padding, and reservemyloan.com is to check the
// same token. Salesforce's LinkToken class and the Pipedream helpers sign exactly the same
// way. Only a host in LINK_TOKEN_HOSTS, which each script sets just above this block, gets
// the token, never a partner's domain. With no secret the link goes out unsigned, an error
// is logged and `link_token` on this step's output says why; the run is never failed for
// it. This block is identical in every script that signs a link, and link-token.test.ts
// holds them all to one text (#2092).
const SALESFORCE_ID = /^[a-zA-Z0-9]{15}(?:[a-zA-Z0-9]{3})?$/;
const withLinkToken = async (url, recordId) => {
  let host = null;
  try { host = new URL(url).hostname; } catch {}
  if (!LINK_TOKEN_HOSTS.includes(host)) return { url, link_token: 'not_our_host' };
  if (typeof recordId !== 'string' || !SALESFORCE_ID.test(recordId)) return { url, link_token: 'no_record_id' };
  const secret = env.LINK_TOKEN_SECRET;
  if (typeof secret !== 'string' || !secret) {
    console.error('LINK_TOKEN_SECRET is not set, so the link went out without its token (#2089)');
    return { url, link_token: 'missing_secret' };
  }
  try {
    const enc = new TextEncoder();
    const key = await crypto.subtle.importKey('raw', enc.encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const signature = new Uint8Array(await crypto.subtle.sign('HMAC', key, enc.encode(recordId.slice(0, 15))));
    let binary = '';
    for (const byte of signature) binary += String.fromCharCode(byte);
    const token = btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    return { url: `${url}${url.includes('?') ? '&' : '?'}t=${token}`, link_token: 'signed' };
  } catch (err) {
    console.error(`signing the link failed, so it went out without its token (#2089): ${err && err.message}`);
    return { url, link_token: 'sign_failed' };
  }
};
// END link token (#2089)

const applicantId = steps.create_applicant.output.body.id;
const offerLink = await withLinkToken(constants.pennieClickUrl + `/${applicantId}`, applicantId);
return {
  body: {
    requestId: execution.trace_id,
    offers: [
      {
        name: constants.offerName,
        display_name: constants.offerName,
        rate: bidAmount,
        click_url: offerLink.url,
        product_type: constants.productType,
        logo_src: constants.logoSrc,
        offer_title: constants.offerTitle,
        offer_details: constants.offerDetails,
      },
    ],
  },
  ...patch,
  bidAmount,
  link_token: offerLink.link_token,
};
